import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ userName, userUsername, grade, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [materials, setMaterials] = useState([]);
  const [timetable, setTimetable] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  const [selectedSubject, setSelectedSubject] = useState('');

  // 🟢 Quiz එකක් ඇතුළට ගොස් විභාගය ලිවීම සඳහා අලුත් States
  const [activeQuizId, setActiveQuizId] = useState(null);
  const [activeQuizTitle, setActiveQuizTitle] = useState('');
  const [quizQuestions, setQuizQuestions] = useState([]);
  const [selectedAnswers, setSelectedAnswers] = useState({}); // ළමයා තෝරන උත්තර මතක තබා ගැනීමට

  const fetchStudentData = () => {
    axios.get('http://localhost:8081/api/learning-materials')
      .then(res => setMaterials(res.data.filter(m => m.grade === grade)))
      .catch(err => console.log(err));

    axios.get('http://localhost:8081/api/timetable')
      .then(res => setTimetable(res.data.filter(c => c.grade === grade)))
      .catch(err => console.log(err));

    axios.get('http://localhost:8081/api/quizzes')
      .then(res => setQuizzes(res.data.filter(q => q.grade === grade)))
      .catch(err => console.log(err));
  };

  useEffect(() => { fetchStudentData(); }, [grade]);

  // 🟢 ළමයා Quiz එකක් Start Attempt කරද්දී ප්‍රශ්න කියවීම
  const handleStartQuiz = (quizId, quizTitle) => {
    setActiveQuizId(quizId);
    setActiveQuizTitle(quizTitle);
    setSelectedAnswers({}); // කලින් සේව් වුණු උත්තර ක්ලියර් කිරීම
    
    axios.get(`http://localhost:8081/api/questions/${quizId}`)
      .then(res => {
        setQuizQuestions(res.data);
        setActiveTab('live-exam'); // කෙලින්ම විභාග ශාලාවට (Exam Window) රැගෙන යයි
      }).catch(err => console.log(err));
  };

  // ළමයා MCQ එකක් ක්ලික් කරද්දී ඒ Answer එක මතක තබා ගැනීම
  const handleSelectOption = (questionId, optionChosen) => {
    setSelectedAnswers({
      ...selectedAnswers,
      [questionId]: optionChosen
    });
  };

  // 🟢 විභාගය අවසානයේ Submit කිරීම සහ ලකුණු බැලීම
  const handleSubmitExam = () => {
    let score = 0;
    quizQuestions.forEach(q => {
      if (selectedAnswers[q.id] === q.correct_option) {
        score += parseInt(q.marks || 2);
      }
    });

    alert(`🎉 Exam Submitted Successfully!\n\nYou scored: ${score} Marks for ${activeQuizTitle}`);
    setActiveQuizId(null);
    setActiveTab('quiz'); // නැවත ක්විස් පේජ් එකට රැගෙන යයි
  };

  const displayedMaterials = selectedSubject ? materials.filter(m => m.subject === selectedSubject) : materials;

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px', boxShadow: '0 4px 15px rgba(21,128,61,0.2)', position: 'relative', overflow: 'hidden' }}>
              <div style={{ position: 'relative', zIndex: 2 }}>
                <h1 style={{ margin: '0 0 10px 0', fontSize: '28px' }}>Welcome back, {userName || 'Student'}! 🧑‍🎓</h1>
                <p style={{ margin: 0, opacity: 0.9, fontSize: '15px' }}>Access your online classrooms, download handouts, and join live quizzes instantly.</p>
              </div>
              <div style={{ position: 'absolute', right: '-10px', top: '-40px', fontSize: '150px', opacity: 0.1, zIndex: 1 }}>🎓</div>
            </div>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="My Registered Grade" count={grade || 'Grade 9'} icon="🏫" color="#f5f3ff" textColor="#7c3aed" />
              <DashboardCard title="Available Handouts" count={`${materials.length} Materials`} icon="📂" color="#eff6ff" textColor="#3b82f6" />
              <DashboardCard title="Pending Quizzes" count={`${quizzes.length} Papers`} icon="📝" color="#fefce8" textColor="#eab308" />
            </div>

            <h2 style={{ color: '#1e293b', margin: '0 0 15px 0', fontSize: '20px' }}>🏫 My Classrooms (Grade 9 IT / Mapped Subjects)</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                {timetable.map(c => (
                  <div key={c.id} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', borderTop: `5px solid #3b82f6` }}>
                    <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' }}>{c.grade}</div>
                    <h3 style={{ margin: '0 0 5px 0', color: '#1e293b', fontSize: '18px' }}>{c.subject}</h3>
                    <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 15px 0' }}>🧑‍🏫 Teacher: {c.teacher}</p>
                    <button onClick={() => { setSelectedSubject(c.subject); setActiveTab('materials'); }} style={styles.enterClassBtn}>📖 Enter Classroom</button>
                  </div>
                ))}
            </div>
          </div>
        );

      case 'materials':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📚 My Learning Materials ({grade})</h2>
            {selectedSubject && (
              <div style={{ marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '15px', backgroundColor: '#e0f2fe', padding: '12px 20px', borderRadius: '10px' }}>
                <button onClick={() => setSelectedSubject('')} style={styles.allSubjectsBtn}>⬅️ All Subjects</button>
                <span style={{ fontSize: '14px', fontWeight: 'bold', color: '#0369a1' }}>Showing lessons for: {selectedSubject}</span>
              </div>
            )}
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px' }}><th>Material Title</th><th>Type</th><th>Action</th></tr>
                </thead>
                <tbody>
                  {displayedMaterials.map(m => (
                    <tr key={m.id} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px' }}>
                      <td style={{ padding: '15px 10px', fontWeight: 'bold' }}>{m.title} <span style={{fontSize:'11px', color:'#94a3b8'}}>({m.subject})</span></td>
                      <td><span style={{ padding: '4px 10px', borderRadius: '4px', fontSize: '11px', fontWeight: 'bold', backgroundColor: m.material_type === 'PDF' ? '#fee2e2' : '#e0f2fe', color: m.material_type === 'PDF' ? '#ef4444' : '#0ea5e9' }}>{m.material_type}</span></td>
                      <td>
                        {m.material_type === 'PDF' ? (
                          <a href={`http://localhost:8081/${m.file_path}`} target="_blank" rel="noopener noreferrer" style={downloadBtnStyle}>📥 Download PDF</a>
                        ) : (
                          <a href={m.file_path} target="_blank" rel="noopener noreferrer" style={videoBtnStyle}>▶️ Watch Video</a>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );

      case 'quiz':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📝 Online Quizzes & Mock Exams ({grade})</h2>
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px' }}><th>Exam Paper Title</th><th>Subject</th><th style={{ textAlign: 'center' }}>Status</th></tr>
                </thead>
                <tbody>
                  {quizzes.map(q => (
                    <tr key={q.id} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px' }}>
                      <td style={{ padding: '15px 10px', fontWeight: 'bold' }}>{q.title}</td>
                      <td style={{ color: '#475569' }}>{q.subject_name}</td>
                      <td style={{ textAlign: 'center' }}>
                        {/* 🟢 මෙතන ක්ලික් කරපු ගමන් ළමයාට ඇත්තටම Exam එක ලියන්න පුළුවන් */}
                        <button onClick={() => handleStartQuiz(q.id, q.title)} style={startQuizBtn}>Start Attempt 🚀</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );

      // 🟢 🟨 NEW TAB VIEW: LIVE EXAM ATTEMPT PAPER (ළමයා ලයිව් විභාගය ලියන තැන!)
      case 'live-exam':
        return (
          <div style={{ animation: 'fadeIn 0.5s', maxWidth: '800px', margin: '0 auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#1e293b', padding: '20px', borderRadius: '12px', color: 'white', marginBottom: '25px' }}>
              <div>
                <h3 style={{ margin: 0 }}>✍️ Active Exam Session</h3>
                <p style={{ margin: '5px 0 0 0', fontSize: '14px', color: '#38bdf8', fontWeight: 'bold' }}>{activeQuizTitle}</p>
              </div>
              <button onClick={handleSubmitExam} style={{ padding: '10px 20px', backgroundColor: '#16a34a', color: 'white', border: 'none', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer' }}>Submit Exam 📥</button>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              {quizQuestions.map((q, idx) => (
                <div key={q.id} style={{ backgroundColor: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', border: '1px solid #e2e8f0' }}>
                  <div style={{ fontSize: '12px', color: '#64748b', fontWeight: 'bold', marginBottom: '8px' }}>QUESTION 0{idx + 1} ({q.marks} Marks)</div>
                  <h3 style={{ margin: '0 0 15px 0', color: '#1e293b', fontSize: '16px' }}>{q.question_text}</h3>
                  
                  {/* MCQ Answers Selection Options */}
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    <label style={styles.examOpt}><input type="radio" name={`q-${q.id}`} checked={selectedAnswers[q.id] === 'A'} onChange={() => handleSelectOption(q.id, 'A')} /> A) {q.option_a}</label>
                    <label style={styles.examOpt}><input type="radio" name={`q-${q.id}`} checked={selectedAnswers[q.id] === 'B'} onChange={() => handleSelectOption(q.id, 'B')} /> B) {q.option_b}</label>
                    <label style={styles.examOpt}><input type="radio" name={`q-${q.id}`} checked={selectedAnswers[q.id] === 'C'} onChange={() => handleSelectOption(q.id, 'C')} /> C) {q.option_c}</label>
                    <label style={styles.examOpt}><input type="radio" name={`q-${q.id}`} checked={selectedAnswers[q.id] === 'D'} onChange={() => handleSelectOption(q.id, 'D')} /> D) {q.option_d}</label>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );

      case 'forum':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2>💬 Student Discussion Forum</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px' }}>
                <p>📢 <strong>Teacher Announcement:</strong> Please make sure to download the Grade 9 IT Term Revision Notes before the live exam sessions!</p>
            </div>
          </div>
        );

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2>👤 Student Profile Settings</h2>
            <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', maxWidth: '450px' }}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                <div><label style={labelStyle}>Full Name</label><input type="text" value={userName} disabled style={disabledInput} /></div>
                <div><label style={labelStyle}>Current Registered Grade</label><input type="text" value={grade} disabled style={disabledInput} /></div>
              </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', flexShrink: 0 }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>STUDENT PORTAL</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px', overflowY: 'auto' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard Overview" />
          <SidebarBtn active={activeTab === 'materials'} onClick={() => setActiveTab('materials')} icon="📚" text="My Learning Materials" />
          <SidebarBtn active={activeTab === 'quiz' || activeTab === 'live-exam'} onClick={() => setActiveTab('quiz')} icon="📝" text="My Online Exams" />
          <SidebarBtn active={activeTab === 'forum'} onClick={() => setActiveTab('forum')} icon="💬" text="Class Forum Space" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="Profile Identity" />
        </div>
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}><button onClick={handleLogout} style={logoutBtnStyle}>🚪 Logout Portal</button></div>
      </div>
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>{renderContent()}</div>
    </div>
  );
}

// --- SIDE STYLES ---
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, color, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}` }}>
    <div><p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p><h2 style={{ margin: 0, color: '#1e293b', fontSize: '22px' }}>{count}</h2></div>
    <div style={{ width: '55px', height: '55px', borderRadius: '12px', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '26px' }}>{icon}</div>
  </div>
);

const labelStyle = { display: 'block', marginBottom: '6px', color: '#475569', fontSize: '13px', fontWeight: 'bold' };
const disabledInput = { width: '100%', padding: '12px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f1f5f9', color: '#334155', outline: 'none', boxSizing: 'border-box', fontSize: '14px' };
const downloadBtnStyle = { padding: '8px 15px', backgroundColor: '#eff6ff', color: '#1d4ed8', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', textDecoration: 'none', display: 'inline-block' };
const videoBtnStyle = { padding: '8px 15px', backgroundColor: '#ecfdf5', color: '#047857', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', textDecoration: 'none', display: 'inline-block' };
const startQuizBtn = { padding: '8px 16px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' };
const logoutBtnStyle = { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px' };

const styles = {
  enterClassBtn: { width: '100%', padding: '10px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', marginTop: '10px' },
  allSubjectsBtn: { padding: '6px 12px', backgroundColor: 'white', border: '1px solid #cbd5e1', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px', color: '#475569' },
  examOpt: { display: 'flex', alignItems: 'center', gap: '10px', backgroundColor: '#f8fafc', padding: '12px 15px', borderRadius: '8px', cursor: 'pointer', border: '1px solid #e2e8f0', fontSize: '14px', color: '#334155', transition: '0.2s' }
};
